use tsr_ast::{Node,NodeId,NodeMap};
use tsr_binder::{SymbolId,SymbolFlags};
use symbol_access::CheckerSymbols;
mod symbol_access;
#[derive(Clone,Copy,Debug,PartialEq,Eq,Hash)]
pub struct TypeId(u32);
const INTERNAL_EXPORT_STAR: &str = "__export";
struct Checker<'a,'n> { symbols: CheckerSymbols<'a>, node_map:&'n NodeMap<'a> }
impl Checker<'_, '_> {
    fn resolve_external_module_name(&mut self, _: NodeId, _: NodeId) -> Option<SymbolId> {
        panic!("external module resolution is outside this own-export fixture");
    }
    pub(crate) fn get_export_of_module(
        &mut self,
        symbol: SymbolId,
        name: &str,
    ) -> Option<crate::symbol_access::SymbolRef> {
        let symbol = self.symbols.bound(symbol).expect("module lookup belongs to this Program");
        self.get_export_of_module_ref(&symbol, name)
    }
    pub(crate) fn get_export_of_module_ref(
        &mut self,
        symbol: &crate::symbol_access::SymbolRef,
        name: &str,
    ) -> Option<crate::symbol_access::SymbolRef> {
        let entry = self.symbols.view(symbol).expect("selected module reader");
        if !entry.flags().intersects(SymbolFlags::MODULE) {
            return None;
        }
        if let Some(found) = entry.export(name) {
            return Some(found);
        }
        // Not an own export — try the existing selected export-star worker.
        self.get_export_from_star_ref(symbol, name)
    }
    pub(crate) fn get_export_from_star_ref(
        &mut self,
        module: &crate::symbol_access::SymbolRef,
        name: &str,
    ) -> Option<crate::symbol_access::SymbolRef> {
        let mut visited = Vec::new();
        self.get_export_from_star_worker(module, name, &mut visited)
    }
    fn get_export_from_star_worker(
        &mut self,
        module: &crate::symbol_access::SymbolRef,
        name: &str,
        visited: &mut Vec<crate::symbol_access::SymbolRef>,
    ) -> Option<crate::symbol_access::SymbolRef> {
        if visited.contains(module) {
            return None;
        }
        visited.push(module.clone());

        let stars: Vec<NodeId> = {
            let entry = self.symbols.view(module).expect("selected star owner");
            let star = entry.export(INTERNAL_EXPORT_STAR)?;
            self.symbols.view(&star).expect("selected star edge").declarations().to_vec()
        };

        for declaration in stars {
            let specifier = match self.node_map.get(declaration) {
                Some(Node::ExportDeclaration(node)) => match node.module_specifier {
                    Some(expression) => match Node::from(expression).node_id() {
                        Some(id) => id,
                        None => continue,
                    },
                    None => continue,
                },
                _ => continue,
            };
            let Some(target) = self.resolve_external_module_name(declaration, specifier) else {
                continue;
            };
            // `export =` in a re-exported module: upstream resolves through it
            // before reading the exports.
            let target = self.symbols.bound(target).expect("bound external module result");
            let target = self
                .symbols
                .view(&target)
                .expect("selected external module")
                .export("export=")
                .unwrap_or(target);
            if let Some(found) =
                self.symbols.view(&target).expect("selected star target").export(name)
            {
                return Some(found);
            }
            if let Some(found) = self.get_export_from_star_worker(&target, name, visited) {
                return Some(found);
            }
        }
        None
    }
}
#[cfg(test)]
mod selected_module_export_tests {
    use super::Checker;
    use tsr_binder::SymbolFlags;

    fn fixture(action: impl FnOnce(&mut Checker<'_, '_>, tsr_binder::SymbolId)) {
        let source = "namespace N { export const item = 1; }";
        let arena = tsr_core::Arena::new();
        let parsed = tsr_parser::parse(&arena, source);
        assert!(parsed.diagnostics.is_empty());
        let bound = tsr_binder::bind(
            &arena,
            parsed.source_file,
            &parsed.nodes,
            tsr_binder::FileInfo { name: "control.ts", text: source },
        );
        let module = bound
            .symbols()
            .iter()
            .find(|(_, symbol)| symbol.name == "N" && symbol.flags.intersects(SymbolFlags::MODULE))
            .unwrap()
            .0;
        let mut checker = Checker { symbols: crate::CheckerSymbols::new(bound.symbols(), crate::TypeId(0)), node_map: &parsed.node_map };
        action(&mut checker, module);
    }

    #[test]
    fn module_exports_keep_selected_private_table_edges() {
        fixture(|checker, module_id| {
            let module = checker.symbols.bound(module_id).unwrap();
            let item = checker.symbols.view(&module).unwrap().export("item").unwrap();
            let first = checker.symbols.clone_symbol(&module).unwrap();
            let second = checker.symbols.clone_symbol(&module).unwrap();
            let first_item = checker.symbols.clone_symbol(&item).unwrap();
            let second_item = checker.symbols.clone_symbol(&item).unwrap();
            checker.symbols.set_export(&first, "item".into(), &first_item).unwrap();
            checker.symbols.set_export(&second, "item".into(), &second_item).unwrap();
            assert_ne!(first_item, second_item);
            for _ in 0..2 {
                assert_eq!(
                    checker.get_export_of_module_ref(&first, "item"),
                    Some(first_item.clone())
                );
                assert_eq!(checker.get_export_of_module_ref(&module, "item"), Some(item.clone()));
                assert_eq!(
                    checker.get_export_of_module_ref(&second, "item"),
                    Some(second_item.clone())
                );
                assert_eq!(checker.get_export_of_module(module_id, "item"), Some(item.clone()));
            }
            checker.symbols.set_export(&first, "added".into(), &second_item).unwrap();
            assert_eq!(checker.get_export_of_module_ref(&first, "added"), Some(second_item));
            assert_eq!(checker.get_export_of_module_ref(&second, "added"), None);
            assert_eq!(checker.get_export_of_module_ref(&module, "added"), None);
        });
    }

    #[test]
    fn module_export_lookup_rejects_nonmodule_tables() {
        fixture(|checker, module_id| {
            let module = checker.symbols.bound(module_id).unwrap();
            let item = checker.symbols.view(&module).unwrap().export("item").unwrap();
            let nonmodule = checker.symbols.clone_symbol(&item).unwrap();
            assert!(
                !checker.symbols.view(&nonmodule).unwrap().flags().intersects(SymbolFlags::MODULE)
            );
            checker.symbols.set_export(&nonmodule, "item".into(), &item).unwrap();
            assert_eq!(checker.symbols.view(&nonmodule).unwrap().export("item"), Some(item));
            assert_eq!(checker.get_export_of_module_ref(&nonmodule, "item"), None);
        });
    }
}

